        { q: "Yesterday, my father ___ a new bicycle for my brother.", options: ["bought", "buys", "buying", "buy"], correctIndex: 0, explanation: "'Yesterday' indicates Simple Past Tense. The past tense of 'buy' is 'bought'." },
        { q: "Look! The children ___ football in the field right now.", options: ["are playing", "is playing", "played", "plays"], correctIndex: 0, explanation: "'Right now' indicates Present Continuous Tense, and 'children' is plural -> 'are playing'." },
        { q: "I have ___ my homework before dinner.", options: ["finished", "finish", "finishing", "finishes"], correctIndex: 0, explanation: "Present Perfect Tense uses 'have/has + past participle' -> 'have finished'." },
        { q: "While Amir was reading, his sister ___ to music.", options: ["was listening", "is listening", "listens", "will listen"], correctIndex: 0, explanation: "Two simultaneous actions in the past use Past Continuous Tense -> 'was listening'." },
        { q: "We ___ visit our grandparents in Melaka next weekend.", options: ["will", "did", "was", "were"], correctIndex: 0, explanation: "'Next weekend' refers to the future, so use 'will'." },
        { q: "The sun ___ in the east.", options: ["rises", "rise", "rose", "rising"], correctIndex: 0, explanation: "General truths and scientific facts use Simple Present Tense -> 'rises'." },
        { q: "Did you ___ the science experiment yesterday?", options: ["complete", "completed", "completing", "completes"], correctIndex: 0, explanation: "After 'Did', always use the base form of the verb -> 'complete'." },
        { q: "They ___ in Selangor since 2018.", options: ["have lived", "lived", "are living", "live"], correctIndex: 0, explanation: "'Since 2018' shows an action starting in the past and continuing to the present -> 'have lived'." },
        { q: "Sarah ___ her ankle while she was jogging.", options: ["sprained", "sprains", "sprain", "is spraining"], correctIndex: 0, explanation: "A sudden past action interrupting an ongoing past action uses Simple Past Tense -> 'sprained'." },
        { q: "Years ago, people ___ send letters by post instead of emails.", options: ["used to", "use to", "using to", "are using to"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "'Used to + base verb' describes regular habits or situations in the past that no longer happen." },
        { q: "Have you ___ visited the National Museum in Kuala Lumpur?", options: ["ever", "yesterday", "ago", "yet"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "'Ever' is used in Present Perfect questions to ask about life experiences up to now." },
        { q: "Puan Rozita has taught English at this school ___ 2019.", options: ["since", "for", "during", "ago"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "Use 'since' with a starting point in time (2019) and 'for' with a duration (e.g. five years)." },
        { q: "According to the museum timetable, the exhibition ___ at 9:00 a.m. tomorrow.", options: ["opens", "open", "opening", "was open"], correctIndex: 0, diff: "H", part: "A", src: "DSKP", explanation: "Present Simple ('opens') is used for scheduled future timetable events." }
