        { q: "Amir and Danial are both 145 cm tall. Amir is ___ Danial.", options: ["as tall as", "taller as", "so tall than", "too tall for"], correctIndex: 0, diff: "L", part: "A", src: "DSKP", explanation: "'as + adjective + as' compares two things that are equal." },
        { q: "A bicycle is ___ a high-speed train.", options: ["not as fast as", "as faster as", "not fast than", "faster as"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "'not as + adjective + as' shows that two things are unequal." },
        { q: "This soup is ___ hot to drink right now; let it cool for five minutes.", options: ["too", "enough", "as", "much"], correctIndex: 0, diff: "L", part: "A", src: "DSKP", explanation: "'too + adjective' means more than is good or possible." },
        { q: "Farah cannot reach the top shelf because she is ___ to get the box.", options: ["not tall enough", "enough tall", "too tall", "as tall"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "'Enough' goes AFTER the adjective: 'not tall enough'." },
        { q: "Maya said, 'I love reading mystery stories.' In reported speech: Maya said that she ___ reading mystery stories.", options: ["loved", "loves", "will love", "loving"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "In reported speech after 'said', Present Simple ('love') shifts back to Past Simple ('loved')." },
        { q: "Hakimi said, 'I am tired after training.' In reported speech: Hakimi said that he ___ tired after training.", options: ["was", "is", "were", "will be"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "'Am' shifts to 'was' for singular 'he' in reported speech." },
        { q: "Rani said, 'I will help you carry the books.' In reported speech: Rani said that she ___ help me carry the books.", options: ["would", "will", "can", "was"], correctIndex: 0, diff: "H", part: "A", src: "DSKP", explanation: "'Will' in direct speech changes to 'would' in reported speech." },
        { q: "The pupils said, 'We can finish the project.' In reported speech: The pupils said that they ___ finish the project.", options: ["could", "can", "will", "are"], correctIndex: 0, diff: "H", part: "A", src: "DSKP", explanation: "Modal 'can' changes to 'could' in reported speech." },
        { q: "This science museum is very interesting, ___?", options: ["isn't it", "is it", "aren't they", "doesn't it"], correctIndex: 0, diff: "L", part: "A", src: "DSKP", explanation: "A positive statement with 'is' takes the negative question tag 'isn't it'." },
        { q: "You don't know the secret password, ___?", options: ["do you", "don't you", "are you", "did you"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "A negative statement with 'don't' takes the positive question tag 'do you'." },
        { q: "They visited the historical museum last weekend, ___?", options: ["didn't they", "did they", "don't they", "weren't they"], correctIndex: 0, diff: "H", part: "A", src: "DSKP", explanation: "Positive Past Simple ('visited') uses the auxiliary 'didn't they' in the question tag." },
        { q: "Your little brother can't swim yet, ___?", options: ["can he", "can't he", "does he", "isn't he"], correctIndex: 0, diff: "M", part: "A", src: "DSKP", explanation: "A negative modal ('can't') is followed by the positive tag 'can he'." }
